async function square(){
 const [imports,unmatchedRaw,txRaw]=await Promise.all([api('/api/square/imports'),api('/api/square/unmatched'),api('/api/square/transactions?limit=100')]);const q=pageFilter('square','q',''),status=pageFilter('square','status','all'),sort=pageFilter('square','sort','transaction_at'),dir=pageFilter('square','dir','desc');let tx=txRaw.filter(x=>textMatch(x,q,['item_name','sku','product_family','variant','location','channel']));let unmatched=unmatchedRaw.filter(x=>textMatch(x,q,['item_name','sku','location']));if(status==='matched')tx=tx.filter(x=>x.product_family);if(status==='unmatched')tx=tx.filter(x=>!x.product_family);tx=sortRows(tx,sort,dir);unmatched=sortRows(unmatched,sort,dir);const totalSales=tx.reduce((a,x)=>a+Number(x.net_sales||0),0);
 $('#content').innerHTML=`
 <div class="cards"><div class="card"><div class="label">Imported batches</div><div class="value">${imports.length}</div><div class="foot">Recent uploads retained for audit</div></div><div class="card"><div class="label">Unmatched sales</div><div class="value">${unmatchedRaw.length}</div><div class="foot">SKU does not match a product</div></div><div class="card"><div class="label">Filtered net sales</div><div class="value">${money(totalSales)}</div><div class="foot">Across ${tx.length} displayed rows</div></div></div>
 ${filterBar('square',{placeholder:'Search item, SKU, product, location',statusOptions:[{value:'matched',label:'Matched'},{value:'unmatched',label:'Unmatched'}],sortOptions:[{value:'transaction_at',label:'Date'},{value:'item_name',label:'Item'},{value:'net_sales',label:'Net sales'},{value:'quantity',label:'Quantity'}]})}
 <div class="panel"><div class="panel-head"><div><h2>Square CSV upload</h2><div class="muted">Upload the Itemized Sales CSV exported from Square. SKU matching controls inventory deductions.</div></div><button onclick="openSquareUpload()">Upload CSV</button></div><div class="square-help"><strong>Before uploading:</strong> make sure each inventory product has its Square SKU entered. The upload is safe to repeat; existing rows and stock deductions are deduplicated automatically.</div></div>
 <div class="panel"><div class="panel-head"><div><h2>Unmatched SKU rows</h2><div class="muted">These sales are stored but cannot change inventory until their SKU matches a product.</div></div><button class="secondary" onclick="navigate('inventory')">Edit product SKUs</button></div>${table(['Date','Item','SKU','Qty','Net sales','Location'],unmatched.slice(0,100).map(x=>`<tr><td>${esc(x.transaction_at?new Date(x.transaction_at).toLocaleString():'—')}</td><td><strong>${esc(x.item_name||'—')}</strong></td><td><span class="sku-code">${esc(x.sku||'No SKU')}</span></td><td>${num(x.quantity)}</td><td>${money(x.net_sales)}</td><td>${esc(x.location||'—')}</td></tr>`))}</div>
 <div class="panel"><div class="panel-head"><div><h2>Import history</h2><div class="muted">Each upload records what was new, duplicated, matched, and applied to inventory.</div></div></div><div class="square-help"><strong>Mistaken upload?</strong> Use the red <strong>Delete upload</strong> button at the beginning of that row. The app previews what will be removed before anything is deleted.</div>${table(['Action','Imported','File','Rows','New','Duplicates','Matched','Unmatched','Stock updates','Inventory cutoff'],imports.map(x=>`<tr><td><button class="danger" type="button" onclick="deleteSquareImport('${x.id}')">Delete upload</button></td><td>${esc(x.imported_at?new Date(x.imported_at).toLocaleString():'—')}</td><td><strong>${esc(x.filename)}</strong></td><td>${x.rows_seen}</td><td>${x.rows_imported}</td><td>${x.rows_duplicate}</td><td>${x.rows_matched}</td><td>${x.rows_unmatched}</td><td>${x.inventory_transactions_created}</td><td>${dateText(x.apply_inventory_from)}</td></tr>`))}</div>
 <div class="panel"><div class="panel-head"><div><h2>Recent Square rows</h2><div class="muted">Raw imported sales with their current product match. Use Delete only when an individual row was imported by mistake.</div></div></div>${table(['Action','Date','Item','SKU','Product','Qty','Net sales','Channel'],tx.map(x=>`<tr><td><button class="danger" type="button" onclick="deleteSquareTransaction('${x.id}')">Delete</button></td><td>${esc(x.transaction_at?new Date(x.transaction_at).toLocaleString():'—')}</td><td>${esc(x.item_name||'—')}</td><td><span class="sku-code">${esc(x.sku||'—')}</span></td><td>${x.product_family?`<strong>${esc(x.product_family)}</strong><br><span class="muted">${esc(x.variant||'')}</span>`:'<span class="need">Unmatched</span>'}</td><td>${num(x.quantity)}</td><td>${money(x.net_sales)}</td><td>${esc(x.channel||'—')}</td></tr>`))}</div>`;
}

async function deleteSquareImport(batchId){
 try{
   const p=await api(`/api/square/imports/${batchId}/preview-delete`);
   const b=p.batch||{};
   const message=`Delete Square upload "${b.filename||'this upload'}"?

This will remove ${num(p.square_rows)} imported Square rows and reverse ${num(p.inventory_transactions)} inventory transaction(s) created from those rows. Any fair assignments for those rows will also be removed.

This cannot be undone except by re-uploading the CSV.`;
   if(!confirm(message))return;
   const r=await api(`/api/square/imports/${batchId}`,{method:'DELETE'});
   toast(`Deleted ${r.square_rows_deleted} Square rows and reversed ${r.inventory_transactions_deleted} stock updates`);
   await refreshCurrent();
 }catch(e){toast(e.message,true)}
}
async function deleteSquareTransaction(id){
 if(!confirm('Delete this Square row? If it changed inventory, that stock change will also be reversed. Any vendor-fair assignment for this row will be removed.'))return;
 try{const r=await api(`/api/square/transactions/${id}`,{method:'DELETE'});toast(`Square row deleted${r.inventory_transactions_deleted?' and inventory restored':''}`);await refreshCurrent()}catch(e){toast(e.message,true)}
}

function openSquareUpload(){
 $('#modal-title').textContent='Upload Square sales CSV';
 $('#modal-help').textContent='Use Square Dashboard → Reports → Item Sales / Itemized Sales and export CSV.';
 $('#modal-body').innerHTML=`
   <div class="field full"><label>Square CSV file</label><input id="square-file" type="file" accept=".csv,text/csv" required /></div>
   <div class="field full"><label>Apply inventory deductions for sales on/after</label><input id="square-cutoff" type="date" value="${new Date().toISOString().slice(0,10)}" /><small class="field-help">This protects your manually entered starting stock from old sales. Raw Square history before this date is still imported, but it will not reduce inventory.</small></div>
   <div class="field full"><div class="square-help"><strong>SKU matching:</strong> Square's SKU must exactly match the Square SKU on an Inventory product. Refund rows with negative quantity add stock back automatically.</div></div>`;
 $('#modal-save').textContent='Upload';
 $('#modal-save').onclick=async()=>{
   try{
     const input=$('#square-file');
     if(!input.files||!input.files[0]){input.reportValidity();return}
     const fd=new FormData();fd.append('file',input.files[0]);const cutoff=$('#square-cutoff').value;if(cutoff)fd.append('apply_inventory_from',cutoff);
     $('#modal-save').disabled=true;$('#modal-save').textContent='Uploading…';
     const result=await api('/api/square/upload',{method:'POST',body:fd});
     closeModal();
     toast(`Square import: ${result.rows_imported} new, ${result.rows_duplicate} duplicate, ${result.inventory_transactions_created} stock updates`);
     await refreshCurrent();
   }catch(e){toast(e.message,true)}finally{$('#modal-save').disabled=false;$('#modal-save').textContent='Save'}
 };
 $('#modal').showModal();
}

