function vendorFairFields(f={}){return field('name','Event name','text',{required:true,value:f.name||''})+field('event_type','Event type','select',{options:['Craft Fair','Festival','School Fair','Maker Market','Convention','Holiday Market','Community Event','Other'],value:f.event_type||''})+field('location','Location','text',{value:f.location||''})+field('start_date','Start date','date',{required:true,value:f.start_date||''})+field('end_date','End date','date',{value:f.end_date||''})+field('selling_start_time','Selling start time','time',{value:f.selling_start_time||''})+field('selling_end_time','Selling end time','time',{value:f.selling_end_time||''})+field('planning_mode','Inventory planning mode','select',{options:[{value:'conservative',label:'Conservative — assume 100% sells'},{value:'historical',label:'Historical — use reconciled events of this type'},{value:'custom',label:'Custom — use my sell-through %'}],value:f.planning_mode||'conservative'})+field('custom_sell_through_percent','Custom sell-through %','number',{min:0,max:100,step:'1',value:f.custom_sell_through_percent??''})+field('booth_fee','Booth fee','number',{min:0,step:'0.01',value:f.booth_fee??0})+field('revenue','Revenue','number',{min:0,step:'0.01',value:f.revenue??''})+field('hours_open','Total selling hours','number',{min:0,step:'0.25',value:f.hours_open??''})+field('attendance_estimate','Estimated attendance','number',{min:0,step:'1',value:f.attendance_estimate??''})+field('weather_conditions','Weather / conditions','text',{value:f.weather_conditions||''})+field('booth_location_quality','Booth location','select',{options:['Excellent','Good','Average','Poor'],value:f.booth_location_quality||''})+field('would_return','Would return?','select',{options:[{value:'',label:'Not decided'},{value:'true',label:'Yes'},{value:'false',label:'No'}],value:f.would_return==null?'':String(f.would_return)})+field('notes','Notes / lessons learned','textarea',{full:true,value:f.notes||''})}
function normalizeVendorFair(d){d.booth_fee=Number(d.booth_fee||0);if(d.revenue!==''&&d.revenue!=null)d.revenue=Number(d.revenue);else d.revenue=null;if(d.hours_open!==''&&d.hours_open!=null)d.hours_open=Number(d.hours_open);else d.hours_open=null;if(d.attendance_estimate!==''&&d.attendance_estimate!=null)d.attendance_estimate=Number(d.attendance_estimate);else d.attendance_estimate=null;if(d.custom_sell_through_percent!==''&&d.custom_sell_through_percent!=null)d.custom_sell_through_percent=Number(d.custom_sell_through_percent);else d.custom_sell_through_percent=null;if(d.planning_mode!=='custom')d.custom_sell_through_percent=null;if(d.would_return==='true')d.would_return=true;else if(d.would_return==='false')d.would_return=false;else d.would_return=null;return d}
function addVendorFair(){openModal('Add vendor fair','Future events appear as countdowns on the dashboard. Add revenue later to rank past events.',vendorFairFields(),async d=>{await api('/api/vendor-fairs',{method:'POST',body:JSON.stringify(normalizeVendorFair(d))})})}
function editVendorFair(id){const f=state.vendorFairs.find(x=>x.id===id);if(!f)return;openModal('Edit vendor fair','Update dates, revenue, booth fee, or notes.',vendorFairFields(f),async d=>{await api(`/api/vendor-fairs/${id}`,{method:'PATCH',body:JSON.stringify(normalizeVendorFair(d))})})}
async function deleteVendorFair(id){const f=state.vendorFairs.find(x=>x.id===id);if(!f)return;if(!confirm(`Delete vendor fair "${f.name}"?`))return;try{await api(`/api/vendor-fairs/${id}`,{method:'DELETE'});toast('Vendor fair deleted');await refreshCurrent()}catch(e){toast(e.message,true)}}


function bytesText(v){const n=Number(v||0);if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;if(n<1024*1024*1024)return `${(n/1024/1024).toFixed(1)} MB`;return `${(n/1024/1024/1024).toFixed(2)} GB`}
async function admin(){
 const [cfg,b]=await Promise.all([api('/api/admin/settings'),api('/api/admin/backups')]);
 const latest=b.latest?new Date(b.latest.created_at).toLocaleString():'Never';
 const rowsHtml=(b.backups||[]).map(x=>`<tr><td><strong>${esc(x.filename)}</strong></td><td>${esc(new Date(x.created_at).toLocaleString())}</td><td>${bytesText(x.size_bytes)}</td><td><div class="row-actions"><a class="button-link secondary" href="/api/admin/backups/${encodeURIComponent(x.filename)}/download">Download</a><button class="danger" onclick="deleteBackup('${esc(x.filename)}')">Delete</button></div></td></tr>`);
 const ops=(b.operations||[]).map(x=>`<tr><td>${esc(new Date(x.started_at).toLocaleString())}</td><td>${badge(x.operation)}</td><td>${badge(x.status)}</td><td>${esc(x.filename||'—')}</td><td>${esc(x.message||'—')}</td></tr>`);
 $('#content').innerHTML=`
 <div class="cards"><div class="card"><div class="label">Backup health</div><div class="value ${b.healthy?'ok':'need'}">${b.healthy?'Good':'Attention'}</div><div class="foot">Latest: ${esc(latest)}</div></div><div class="card"><div class="label">Backup files</div><div class="value">${(b.backups||[]).length}</div><div class="foot">Retention ${cfg.backup_retention_days} days</div></div><div class="card"><div class="label">Scheduled backup</div><div class="value">3:00 AM</div><div class="foot">Cron: ${esc(cfg.backup_cron)}</div></div></div>
 <div class="two-col"><div class="panel"><div class="panel-head"><div><h2>Backups</h2><div class="muted">Nightly backups plus manual snapshots.</div></div><button onclick="createBackupNow()">Back Up Now</button></div>${table(['File','Created','Size','Actions'],rowsHtml)}</div>
 <div class="panel"><div class="panel-head"><div><h2>Restore database</h2><div class="muted">Restore a .dump file created by this app.</div></div></div><div class="restore-warning"><strong>Restore replaces the current database.</strong><br>The app automatically creates a safety backup immediately before restoring. Use this only when you intentionally want to roll back the database.</div><div style="margin-top:14px"><button class="danger" onclick="openRestoreBackup()">Restore from Backup</button></div></div></div>
 <div class="panel"><div class="panel-head"><div><h2>Application settings</h2><div class="muted">Operational defaults stored in Postgres.</div></div><button class="secondary" onclick="editAdminSettings()">Edit settings</button></div><div class="settings-grid"><div><span>Business name</span><strong>${esc(cfg.business_name)}</strong></div><div><span>Currency</span><strong>${esc(cfg.currency)}</strong></div><div><span>Timezone</span><strong>${esc(cfg.timezone)}</strong></div><div><span>Default spool weight</span><strong>${num(cfg.default_spool_weight_grams)} g</strong></div><div><span>Backup retention</span><strong>${cfg.backup_retention_days} days</strong></div><div><span>Backup warning</span><strong>${cfg.backup_warning_hours} hours</strong></div></div></div>
 <div class="panel"><div class="panel-head"><div><h2>Backup activity</h2><div class="muted">Recent manual, scheduled, restore, and delete operations.</div></div></div>${table(['Time','Operation','Status','File','Message'],ops)}</div>`;
}
async function createBackupNow(){try{toast('Creating backup…');await api('/api/admin/backups',{method:'POST'});toast('Backup completed');await admin()}catch(e){toast(e.message,true)}}
async function deleteBackup(name){if(!confirm(`Delete backup ${name}?`))return;try{await api(`/api/admin/backups/${encodeURIComponent(name)}`,{method:'DELETE'});toast('Backup deleted');await admin()}catch(e){toast(e.message,true)}}
function editAdminSettings(){api('/api/admin/settings').then(cfg=>openModal('Application settings','These settings are stored in Postgres and survive container rebuilds.',field('business_name','Business name','text',{required:true,value:cfg.business_name})+field('currency','Currency','text',{required:true,value:cfg.currency})+field('timezone','Timezone','text',{required:true,value:cfg.timezone})+field('default_spool_weight_grams','Default spool weight (g)','number',{required:true,min:1,value:cfg.default_spool_weight_grams})+field('backup_retention_days','Backup retention (days)','number',{required:true,min:1,value:cfg.backup_retention_days})+field('backup_warning_hours','Warn if backup older than (hours)','number',{required:true,min:1,value:cfg.backup_warning_hours}),async d=>{d.default_spool_weight_grams=Number(d.default_spool_weight_grams);d.backup_retention_days=Number(d.backup_retention_days);d.backup_warning_hours=Number(d.backup_warning_hours);await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify(d)})})).catch(e=>toast(e.message,true))}
function openRestoreBackup(){
 $('#modal-title').textContent='Restore database backup';$('#modal-help').textContent='A safety backup is created automatically before the restore begins.';
 $('#modal-body').innerHTML=`<div class="field full"><label>PostgreSQL .dump file</label><input id="restore-file" type="file" accept=".dump,application/octet-stream" required /></div><div class="field full"><label>Type RESTORE to confirm</label><input id="restore-confirm" type="text" autocomplete="off" placeholder="RESTORE" required /></div><div class="field full"><div class="restore-warning"><strong>This replaces current database contents.</strong><br>Do not close or refresh the page while the restore is running.</div></div>`;
 const save=$('#modal-save');save.style.display='';save.textContent='Restore Database';save.className='danger';save.onclick=async()=>{const f=$('#restore-file').files[0],c=$('#restore-confirm').value;if(!f){toast('Choose a backup file',true);return}if(c!=='RESTORE'){toast('Type RESTORE exactly to continue',true);return}if(!confirm('Final confirmation: replace the current CFT Inventory database with this backup?'))return;const fd=new FormData();fd.append('file',f);fd.append('confirmation',c);try{save.disabled=true;save.textContent='Restoring…';const result=await api('/api/admin/restore',{method:'POST',body:fd});closeModal();toast(`Restore completed. Safety backup: ${result.safety_backup}`);await admin()}catch(e){save.disabled=false;save.textContent='Restore Database';toast(e.message,true)}};$('#modal').showModal();
}

const pages={dashboard,inventory,production,filament,projects,vendorFairs,square,integrations,admin};
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
checkHealth();navigate('dashboard');

function capacityFields(g={}){return field('name','Group name','text',{required:true,value:g.name||''})+field('printer_count','Printer count','number',{required:true,min:1,value:g.printer_count||1})+field('hours_per_printer_day','Available hours per printer / day','number',{required:true,min:0,step:'0.25',value:g.hours_per_printer_day??16})+field('efficiency_percent','Expected utilization %','number',{required:true,min:1,step:'1',value:g.efficiency_percent??85})+field('notes','Notes','textarea',{full:true,value:g.notes||''});}
function addCapacityGroup(){openModal('Add production capacity','Define a manual printer-capacity group. This does not connect to or control any printer.',capacityFields(),async d=>{d.printer_count=Number(d.printer_count);d.hours_per_printer_day=Number(d.hours_per_printer_day);d.efficiency_percent=Number(d.efficiency_percent);await api('/api/production/capacity-groups',{method:'POST',body:JSON.stringify(d)})})}
function editCapacityGroup(id){const g=(state.productionPlan?.capacity_groups||[]).find(x=>x.id===id);if(!g)return;openModal('Edit production capacity','Adjust the planning assumptions for this printer group.',capacityFields(g),async d=>{d.printer_count=Number(d.printer_count);d.hours_per_printer_day=Number(d.hours_per_printer_day);d.efficiency_percent=Number(d.efficiency_percent);await api(`/api/production/capacity-groups/${id}`,{method:'PATCH',body:JSON.stringify({...d,active:true})})})}
